// DataPopcorn analysis skills exposed over MCP: prompts, resources and three tools.
// Skill text comes from skills-bundle.js (generated by scripts/sync-skills.mjs), never edited here.
import { SKILL_FILES, SKILL_SOURCE } from "./skills-bundle.js";

const file = (skill, name) => SKILL_FILES.find((f) => f.skill === skill && f.file === name);
const skillMd = (skill) => file(skill, "SKILL.md")?.text ?? "";

export const STAGES = {
  pipeline: {
    skill: "data-analysis-pipeline",
    prompt: "analysis_pipeline",
    title: "데이터 분석 4단계 전체 (가설 → 수집 → 의심 → 정리)",
    refs: [],
  },
  "1-hypothesis": { skill: "1-hypothesis", prompt: "analysis_1_hypothesis", title: "① 가설: 목표 인터뷰로 hypothesis.md 만들기", refs: [] },
  "2-collect": {
    skill: "2-collect",
    prompt: "analysis_2_collect",
    title: "② 수집: 데이터 확보·정리와 수집 기록",
    refs: ["references/data-sources-korea.md"],
  },
  "3-suspect": {
    skill: "3-suspect",
    prompt: "analysis_3_suspect",
    title: "③ 의심: EDA와 함정 10개 판정(traps_check.md)",
    refs: ["references/trend-traps.md"],
  },
  "4-report": { skill: "4-report", prompt: "analysis_4_report", title: "④ 정리: 한 장 HTML 리포트", refs: [] },
};
const STAGE_KEYS = Object.keys(STAGES);

// The skills were written for Claude Code (files, Skill tool, python scripts). In a chat app
// connected over MCP those don't exist, so every prompt/tool result starts with this adapter.
const MCP_ADAPTER = `> **MCP 연결 환경 안내 (데이터팝콘 MCP)**
> 아래 스킬은 원래 Claude Code에서 파일을 만들며 쓰도록 작성됐습니다. 지금 환경에서 파일을 만들 수 없다면:
> - 산출물(hypothesis.md, traps_check.md, findings.md 등)은 **대화에 마크다운 블록으로 그대로 출력**합니다. 파일명을 블록 제목으로 붙입니다.
> - "Skill 툴로 호출"은 이 서버의 \`analysis_get_skill\` 도구(또는 \`analysis_*\` 프롬프트)로 해당 단계 지침을 불러오는 것으로 대체합니다.
> - \`1_collect.py\` 같은 스크립트는 사용자가 직접 실행할 수 있는 코드로 제시하고, 실행 결과를 받은 뒤 다음 판단을 합니다.
> - 숫자 점검이 필요하면 \`analysis_suspect_numbers\` 도구로 표본 크기·평균의 함정·기간 공백·급변점을 먼저 계산합니다.
> - 단계 순서(①→②→③→④)와 "산출물이 없으면 다음 단계로 가지 않는다" 규칙은 그대로 지킵니다.`;

function stageText(key, includeRefs) {
  const st = STAGES[key];
  let text = `${MCP_ADAPTER}\n\n${skillMd(st.skill)}`;
  if (includeRefs) {
    for (const r of st.refs) text += `\n\n---\n\n<!-- ${st.skill}/${r} -->\n\n${file(st.skill, r)?.text ?? ""}`;
  }
  return text;
}

// ---------- prompts ----------
const PROMPT_ARGS = [
  { name: "topic", description: "분석하려는 주제나 질문 (예: '점심 매출이 왜 떨어지나')", required: false },
  { name: "context", description: "이미 가진 데이터, 가설, 중간 결과 등 참고할 내용", required: false },
];

export function listPrompts() {
  return STAGE_KEYS.map((k) => ({ name: STAGES[k].prompt, title: STAGES[k].title, description: STAGES[k].title, arguments: PROMPT_ARGS }));
}

export function getPrompt(name, args = {}) {
  const key = STAGE_KEYS.find((k) => STAGES[k].prompt === name);
  if (!key) return null;
  const ask = [args.topic && `분석 주제: ${args.topic}`, args.context && `참고 내용:\n${args.context}`].filter(Boolean).join("\n\n");
  return {
    description: STAGES[key].title,
    messages: [
      {
        role: "user",
        content: { type: "text", text: `${stageText(key, true)}\n\n---\n\n위 지침대로 진행해 주세요.${ask ? `\n\n${ask}` : " 먼저 무엇을 분석할지 한 번에 하나씩 물어봐 주세요."}` },
      },
    ],
  };
}

// ---------- resources ----------
export function listResources() {
  return SKILL_FILES.map((f) => ({ uri: f.uri, name: `${f.skill}/${f.file}`, mimeType: f.mimeType, description: `데이터팝콘 분석 스킬 원문 (${SKILL_SOURCE})` }));
}

export function readResource(uri) {
  const f = SKILL_FILES.find((x) => x.uri === uri);
  return f ? { contents: [{ uri: f.uri, mimeType: f.mimeType, text: f.text }] } : null;
}

